'use strict';
const BUSINESS_UI5={bind,financeView,help};
TITLES.business='Obchod & odběratelé';
const businessTermsLabel5=n=>n?'Za '+n+' týdny':'Při dodání';
function businessTable5(list){return `<div class="table-scroll"><table class="data"><thead><tr><th>Odběratel / týden</th><th>Dodáno / sjednáno</th><th>Tržby</th><th>Přímé náklady</th><th>Příspěvek</th></tr></thead><tbody>${list.map(d=>`<tr><td>${esc(d.name)}<small>T${d.week} · ${esc(d.owner)}</small></td><td>${number(d.delivered,1)} / ${number(d.ordered,1)} kg<small>Kvalita ${number(d.quality,1)} / 100</small></td><td>${money(d.revenue)}<small>Sleva za kvalitu ${number(d.discount*100,1)} %</small></td><td>${money(d.coffee+d.shipping+d.penalty)}<small>Káva ${money(d.coffee)} · doprava ${money(d.shipping)} · pokuta ${money(d.penalty)}</small></td><td class="${d.contribution<0?'bad':'good'}">${money(d.contribution)}</td></tr>`).join('')||'<tr><td colspan="5">Zatím žádná dodávka.</td></tr>'}</tbody></table></div>`;}
function businessView(){const s=state.business5,p=s.policy,last=s.last,exec=state.organization.executives.sales.manager,mandate=state.organization.policies.sales;return `<p class="intro">Vyjednej pravidelný odběr vlastní kávy. Kavárny mají při spotřebě přednost; kontrakty odebírají zbývající skutečné šarže v pořadí podpisu. Jeden obchodník spravuje jeden aktivní kontrakt.</p><div class="report-overview5">${metric('AKTIVNÍ KONTRAKTY',state.contracts.length,'Volní obchodníci: '+businessSlots5())}${metric('OTEVŘENÉ FAKTURY',money(s.invoices.reduce((n,i)=>n+i.amount,0)),s.invoices.length+' čekajících plateb')}${metric('B2B PŘÍSPĚVEK',last?money(last.deliveries.reduce((n,d)=>n+d.contribution,0)):'—','Po kávě, dopravě a pokutách')}${metric('POSLEDNÍ INKASO',last?money(last.collected):'—','Platby starších faktur')}</div><div class="actions"><button class="soft" data-goto="organization">Ředitelé & rozpočty</button><button class="soft" data-goto="hq">Pracovníci Obchodu</button><button class="soft" data-goto="supply">Výroba & zásoby</button><button class="soft" data-goto="performance">Report výkonu</button></div><div class="section-header"><h2>Zákazníci & vyjednávání</h2><span class="sub">Jednání 1 500 Kč · podpis 5 000 Kč</span></div><div class="cards">${CLIENTS5.map(c=>{const a=businessAccount5(c.id),available=state.stores.length&&state.departments.sales&&state.reputation>=c.rep&&!a.contract&&a.negotiated!==state.week&&businessSlots5();return `<section class="card"><div class="card-head"><h3>${esc(c.name)}</h3><span class="badge">${esc(c.city)}</span></div><p class="sub">${c.kind} · ${c.min}–${c.max} kg / týden · požadovaná kvalita ${c.quality}</p>${rows([['Vztah',number(a.relationship,1)+' / 100'],['Požadovaná pověst',c.rep+' / 100'],['Orientační cena',money(c.price)+' / kg'],['Stav',({prospect:'Nový kontakt',active:'Aktivní kontrakt',completed:'Dokončená smlouva',cancelled:'Ukončeno firmou',lost:'Ztracený odběratel'})[a.status]]])}<div class="actions"><button class="primary" data-business-negotiate="${c.id}" ${!available||state.over?'disabled':''}>Vyjednat nabídku</button><button class="quiet" data-business-history="${c.id}">Historie vztahu</button></div>${!available?'<p class="sub">Potřebuješ vlastní kavárnu, volného obchodníka a požadovanou pověst. Aktivní zákazník nebo již oslovený kontakt tento týden další nabídku nepřijímá.</p>':''}</section>`}).join('')}</div><div class="section-header"><h2>Nabídky k podpisu</h2><span class="sub">Platnost do uvedeného týdne včetně</span></div><div class="cards">${s.proposals.filter(p=>p.due>=state.week).map(p=>`<section class="card"><h3>${esc(businessClient5(p.client).name)}</h3><p>${esc(blend(p.blend).name)} · ${p.kg} kg týdně · ${money(p.price)}/kg</p><p class="sub">${p.weeks} týdnů · ${businessTermsLabel5(p.terms)} · platnost T${p.due} · ${esc(p.owner)}${p.asked>p.price?' · protinabídka zákazníka':''}</p><div class="actions"><button class="soft" data-business-preview="${p.id}">Výhled 4 týdny</button><button class="soft" data-business-preview8="${p.id}">Výhled 8 týdnů</button><button class="primary" data-business-sign="${p.id}" ${state.over?'disabled':''}>Prověřit podpis</button></div></section>`).join('')||empty('Žádná platná nabídka. Oslov zákazníka nebo pověř obchodního ředitele.')}</div><div class="section-header"><h2>Aktivní smlouvy</h2></div><div class="cards">${state.contracts.map(c=>`<section class="card"><h3>${esc(c.name)}</h3>${rows([['Káva',esc(blend(c.blend).name)],['Odběr týdně',c.kg+' kg'],['Cena / kg',money(c.price)],['Zbývá',c.remaining+' týdnů'],['Splatnost',businessTermsLabel5(c.business5?.terms||0)],['Minule dodáno',c.last?number(c.last.delivered,1)+' kg':'—'],['Příspěvek minule',c.last?.contribution!==undefined?money(c.last.contribution):'—']])}${c.business5?`<p class="sub">${esc(c.business5.owner)} · kvalita ${c.business5.minQuality} · doprava ${money(c.business5.shipping+(typeof brandingPrintCost5==='function'?brandingPrintCost5(blend(c.blend)):0))}/kg. Tři týdny s plněním pod 80 % nebo vztah pod 25 ukončí odběr.</p><div class="actions"><button class="soft" data-business-renew="${c.id}" ${c.remaining>3||state.over?'disabled':''}>Obnovit smlouvu</button><button class="quiet" data-business-cancel="${c.id}" ${state.over?'disabled':''}>Ukončit za poplatek</button></div>`:'<p class="sub">Dřívější jednoduchý kontrakt · platba při dodání.</p>'}</section>`).join('')||empty('Zatím žádná aktivní smlouva.')}</div><section class="card" style="margin-top:24px"><h2>Mandát obchodního ředitele</h2><p class="sub">${exec?esc(exec.name):'Role zatím není obsazená'} · týdenní limit ${money(mandate.budget)} · rezerva ${mandate.reserve} týdnů fixních nákladů · hlavní mandát ${mandate.enabled?'povolený':'vypnutý'}. Ředitele a jeho hlavní mandát nastav v organizaci. B2B zásahy se provedou pouze při povolení obou mandátů; výběr hlídá kvalitu, kapacitu a peníze na splatnost.</p><label class="checkbox-line"><input type="checkbox" id="businessEnabled5" ${p.enabled?'checked':''}> Povolit řediteli B2B jednání</label><label class="checkbox-line"><input type="checkbox" id="businessAutoSign5" ${p.autoSign?'checked':''}> Povolit také automatický podpis</label><div class="fields">${field('Min. odhad příspěvku / kg',input('businessMargin5',p.minMargin,0,500))}${field('Max. kg na novou smlouvu',input('businessMaxKg5',p.maxKg,10,200))}${field('Nabízená splatnost',`<select id="businessTerms5">${[0,2,4].map(n=>option(n,businessTermsLabel5(n),p.maxTerms)).join('')}</select>`)}</div><button class="primary" id="businessPolicySave5">Uložit mandát</button><p class="sub">Ředitel vybere nejvýše jednu novou zakázku za týden podle odhadovaného příspěvku. Bez automatického podpisu připraví nabídku k tvému rozhodnutí.</p></section><section class="card" style="margin-top:24px"><h2>Skutečné dodávky${last?' · T'+last.week:''}</h2>${businessTable5(last?.deliveries||[])}<p class="sub">Příspěvek odečítá skutečně spotřebovanou kávu, balení, dopravu a pokuty. Mzdy obchodníků, jednání, podpis, pražírny a centrála jsou ve výsledku celé firmy. Kvalita pod požadavkem snižuje cenu o 1,2 % za bod, nejvýše o 25 %.</p></section><section class="card" style="margin-top:24px"><h2>Faktury & inkaso</h2><p class="sub">Tržba vzniká při dodání. Hotovost přijde na začátku týdne splatnosti; inkaso znovu nezvyšuje zisk. Platba při dodání se do pohledávek nezapisuje. Model předpokládá úhradu včas.</p>${businessInvoices5(s.invoices,false)}<h3>Poslední úhrady</h3>${businessInvoices5(s.payments.slice(-20).reverse(),true)}</section>`;}
function businessInvoices5(list,paid){return `<div class="table-scroll"><table class="data"><thead><tr><th>Zákazník</th><th>Částka</th><th>Vystaveno</th><th>${paid?'Uhrazeno':'Splatnost'}</th></tr></thead><tbody>${list.map(i=>`<tr><td>${esc(businessClient5(i.client).name)}<small>${esc(i.id)}</small></td><td>${money(i.amount)}</td><td>T${i.issued}</td><td>T${paid?i.paid:i.due}</td></tr>`).join('')||'<tr><td colspan="4">Žádné faktury.</td></tr>'}</tbody></table></div>`;}
function businessReadOffer5(){return {blend:el('businessBlend5').value,kg:Number(el('businessKg5').value),price:Number(el('businessPrice5').value),weeks:Number(el('businessWeeks5').value),terms:Number(el('businessPay5').value)};}
function businessQuoteHtml5(q){return `${rows([['Zákazníkem přijatelná cena',money(q.counter)+'/kg'],['Odhad nákladu kávy / kg',money(q.unit)],['Balení a doprava / kg',money(q.shipping+(q.printing||0))],['Kvalita dostupné kávy',number(q.quality,1)+' / 100 · požadováno '+q.minQuality],['Odhad příspěvku / kg',money(q.margin)],['Příspěvek při plném odběru / týden',money(q.weeklyContribution)],['Odhad výroby / veškerá potřeba',number(q.capacity,1)+' / '+number(q.demand,1)+' kg']])}<p class="sub">Odhad používá současné šarže nebo recepturu. Kapacita předpokládá tuto recepturu; skutečnou kombinaci káv ověř výhledem. Přímé náklady nezahrnují centrálu a mzdy. ${esc(q.reason)}</p>${q.capacity<q.demand?'<div class="warning">Celková potřeba převyšuje odhad výroby. Hrozí nedodání a pokuty.</div>':''}${q.margin<0?'<div class="warning">Zakázka má odhadovaný záporný příspěvek.</div>':''}${q.quality<q.minQuality?'<div class="warning">Současná kvalita nesplňuje požadavek. Zákazník sníží prodejní cenu.</div>':''}${q.terms?`<div class="warning">Splatnost váže peníze. Přímé náklady před první úhradou přibližně ${money(q.kg*(q.unit+q.shipping)*q.terms)}; další výdaje firmy potřebují vlastní rezervu.</div>`:''}`;}
function businessNegotiateDialog5(id){const c=businessClient5(id);show(`<h2>Jednání · ${esc(c.name)}</h2><div class="fields">${field('Káva',`<select id="businessBlend5">${blendOptions(state.blends[0].id)}</select>`)}${field('kg / týden',input('businessKg5',c.min,c.min,c.max))}${field('Cena / kg',input('businessPrice5',c.price,250,1500))}${field('Délka smlouvy',`<select id="businessWeeks5">${option(12,'12 týdnů',12)}${option(26,'26 týdnů',12)}</select>`)}${field('Splatnost',`<select id="businessPay5">${[0,2,4].map(n=>option(n,businessTermsLabel5(n),0)).join('')}</select>`)}</div><div id="businessQuote5"></div><button class="primary" id="businessNegotiateConfirm5">Odeslat nabídku · 1 500 Kč</button><p class="sub">Zákazník může navrhnout nižší cenu. Jednání zaplatíš nyní; podpis je samostatné rozhodnutí. Jeden kontakt lze oslovit jednou za týden.</p>`);let quoted;const refresh=()=>{try{quoted=businessOffer5(id,businessReadOffer5());el('businessQuote5').innerHTML=businessQuoteHtml5(quoted);el('businessNegotiateConfirm5').disabled=!quoted.eligible||!quoted.freeSlots;}catch(e){quoted=null;el('businessQuote5').textContent=e.message;el('businessNegotiateConfirm5').disabled=true;}};for(const k of ['businessBlend5','businessKg5','businessPrice5','businessWeeks5','businessPay5'])el(k).oninput=el(k).onchange=refresh;refresh();el('businessNegotiateConfirm5').onclick=()=>{try{negotiateBusiness5(id,businessReadOffer5(),quoted);persist();render();el('modal').close();toast('Nabídka zákazníka je připravená k podpisu.');}catch(e){toast(e.message);refresh();}};}
function businessSignDialog5(id){try{const q=businessAcceptance5(id);confirmAction('Podepsat · '+esc(q.offer.name)+'?',`Sjednaná cena ${money(q.proposal.price)}/kg · ${q.proposal.kg} kg týdně · ${q.proposal.weeks} týdnů. Podpis ${money(q.fee)}, hotovost po podpisu ${money(q.remainingCash)}. První odběr proběhne při odehrání týdne.`,()=>acceptBusiness5(id,q),'Podepsat · 5 000 Kč');el('modalContent').querySelector('.actions').insertAdjacentHTML('beforebegin',businessQuoteHtml5(q.offer));}catch(e){toast(e.message);}}
function businessPreviewDialog5(id,weeks){try{const before=JSON.stringify(state),f=previewBusiness5(id,weeks);if(JSON.stringify(state)!==before)throw Error('Náhled změnil stav hry.');show(`<h2>Výhled zakázky · ${weeks} týdnů</h2><p class="sub">Kopie celé firmy po podpisu za ${money(f.fee)}. Proběhla stejná týdenní simulace včetně kaváren, výroby, vedení a soupeřů. Výhled neuložil žádné změny. Nejnižší hotovost ${money(f.minCash)}${f.over?' · firma ve výhledu končí':''}.</p><div class="table-scroll"><table class="data"><thead><tr><th>Týden</th><th>Dodáno / objednáno</th><th>Příspěvek zakázky</th><th>Zisk firmy</th><th>Hotovost firmy</th><th>Všechny pohledávky</th></tr></thead><tbody>${f.series.map(r=>`<tr><td>${r.week}</td><td>${number(r.delivered,1)} / ${number(r.ordered,1)} kg</td><td>${money(r.contribution)}</td><td>${money(r.profit)}</td><td>${money(r.cash)}</td><td>${money(r.receivable)}</td></tr>`).join('')}</tbody></table></div><p class="sub">Výsledek platí pro aktuální nastavení a herní události. Další rozhodnutí nebo nové smlouvy ho mohou změnit.</p>`);}catch(e){toast(e.message);}}
function businessHistoryDialog5(id){const a=businessAccount5(id),c=businessClient5(id);show(`<h2>${esc(c.name)} · vztah ${number(a.relationship,1)} / 100</h2><p class="sub">Posledních 26 dodávek. Výsledky před vznikem B2B evidence se nedoplňují.</p>${businessTable5(a.history.slice().reverse())}`);}
financeView=function(){return `<section class="card" style="margin-bottom:24px"><div class="card-head"><h2>B2B odběratelé & splatnost</h2><button class="primary" data-goto="business">Otevřít obchod</button></div>${rows([['Otevřené pohledávky',money(state.business5.invoices.reduce((n,i)=>n+i.amount,0))],['Poslední inkaso starších faktur',money(state.business5.last?.collected||0)]])}<p class="sub">Tržby při dodání zahrnují i dosud neuhrazené faktury. Inkaso mění hotovost; provozní zisk se podruhé nezvyšuje.</p></section>`+BUSINESS_UI5.financeView();};
bind=function(){BUSINESS_UI5.bind();on('[data-business-negotiate]',b=>businessNegotiateDialog5(b.dataset.businessNegotiate));on('[data-business-sign]',b=>businessSignDialog5(b.dataset.businessSign));on('[data-business-preview]',b=>businessPreviewDialog5(b.dataset.businessPreview,4));on('[data-business-preview8]',b=>businessPreviewDialog5(b.dataset.businessPreview8,8));on('[data-business-history]',b=>businessHistoryDialog5(b.dataset.businessHistory));on('[data-business-cancel]',b=>{try{const id=b.dataset.businessCancel,q=businessCancelQuote5(id);confirmAction('Ukončit odběr?','Poplatek '+money(q.fee)+'. Vztah klesne o 12 bodů. Již vystavené faktury zůstávají splatné.',()=>cancelBusiness5(id,q),'Ukončit kontrakt');}catch(e){toast(e.message);}});on('[data-business-renew]',b=>{try{const id=b.dataset.businessRenew,q=businessRenewalQuote5(id);confirmAction('Obnovit kontrakt?','Dalších '+q.weeks+' týdnů za '+money(q.price)+'/kg. Poplatek '+money(q.fee)+'. Obnova vyžaduje vztah alespoň 55 a dostatek obchodníků.',()=>renewBusiness5(id,q),'Obnovit kontrakt');}catch(e){toast(e.message);}});if(el('businessPolicySave5'))el('businessPolicySave5').onclick=()=>act(()=>setBusinessPolicy5({enabled:el('businessEnabled5').checked,autoSign:el('businessAutoSign5').checked,minMargin:Number(el('businessMargin5').value),maxKg:Number(el('businessMaxKg5').value),maxTerms:Number(el('businessTerms5').value)}),'Mandát obchodu uložen.');};
help=function(){BUSINESS_UI5.help();const p=document.createElement('p');p.textContent='Obchod & odběratelé: vyjednej objem, cenu, délku smlouvy a splatnost. Jednání stojí 1 500 Kč, podpis 5 000 Kč. Před podpisem použij skutečný výhled 4 nebo 8 týdnů. Kavárny spotřebují kávu před kontrakty. Nedodání stojí 15 % hodnoty chybějící kávy; slabá kvalita snižuje cenu. Tři nedodané týdny pod 80 % nebo vztah pod 25 ukončí odběr. Faktury se hradí na začátku týdne splatnosti, i po ukončení smlouvy. V posledních třech týdnech lze smlouvu za poplatek obnovit. B2B mandát ředitele vyžaduje obsazenou roli, hlavní mandát a samostatné povolení B2B; podpis se povoluje zvlášť. Report výkonu obsahuje i historii odběratelů.';el('modalContent').append(p);};el('help').onclick=help;
render();
